117	// acceptSubmission 验收工单当前待验收提交：seq 须等于当前待验收提交的履历序号。
118	// 通过时追加验收履历并沿用一条关闭履历（内容为该次提交的维修结果）终结工单，
119	// 资产恢复可用；退回时追加验收履历，工单恢复未关闭，资产仍为维修中。
120	// 失败路径不修改任何业务数据，也不消耗履历序号。
121	func (s *store) acceptSubmission(ticketID string, seq int, decision, comment string) (*Ticket, *Asset, error) {
122		t := s.findTicket(ticketID)
