130			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能验收", errConflict, ticketID)
131		case ticketOpen:
132			return nil, nil, fmt.Errorf("%w: 工单 %s 当前没有待验收提交", errConflict, ticketID)
133		}
134		curSeq, curResult, ok := s.currentSubmission(ticketID)
135		if !ok {
136			return nil, nil, fmt.Errorf("数据内部错误：待验收工单 %s 缺少当前提交履历", ticketID)
137		}
138		if seq != curSeq {
139			return nil, nil, s.submissionSeqError(ticketID, seq)
140		}
141		eventSeq, err := s.nextEventSeq()
142		if err != nil {
143			return nil, nil, err
144		}
145		asset := s.findAsset(t.AssetID)
146		if asset == nil {
147			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
148		}
149		if decision == decisionApprove {
150			// 通过需同时追加验收与关闭两条履历：先确认序号空间足够，再修改数据。
151			if eventSeq == math.MaxInt {
152				return nil, nil, fmt.Errorf("%w: 履历序号计数器空间不足，无法同时追加验收与关闭履历", errConflict)
153			}
154			s.appendAcceptEvent(eventSeq, t, decision, comment, seq)
155			s.appendEvent(eventSeq+1, t.AssetID, t.ID, eventClose, curResult, "", "")
156			t.Status = ticketClosed
157			t.Result = curResult
158			t.ClosedAt = s.now().Format(time.RFC3339)
159			asset.Status = statusAvailable
160			return t, asset, nil
161		}
162		s.appendAcceptEvent(eventSeq, t, decision, comment, seq)
163		t.Status = ticketOpen
164		return t, asset, nil
165	}
166	
167	// submissionSeqError 为验收目标序号不匹配当前待验收提交时生成指明原因的错误：
168	// 未知序号、非提交序号、跨单提交、已处理或非当前提交分别说明。
169	func (s *store) submissionSeqError(ticketID string, seq int) error {
170		for _, e := range s.data.Events {
171			if e.Seq != seq {
172				continue
173			}
174			if e.Kind != eventSubmit {
175				return fmt.Errorf("%w: 序号 %d 不是维修提交序号（该序号为%s履历）", errConflict, seq, e.Kind)
176			}
177			if e.TicketID != ticketID {
178				return fmt.Errorf("%w: 提交序号 %d 属于工单 %s，不能用于工单 %s 的验收",
179					errConflict, seq, e.TicketID, ticketID)
180			}
181			return fmt.Errorf("%w: 提交序号 %d 已处理，不是工单 %s 当前待验收提交",
182				errConflict, seq, ticketID)
183		}
184		return fmt.Errorf("%w: 未知提交序号 %d", errConflict, seq)
185	}
