157		NewContent   string `json:"new_content,omitempty"`
158		OldContent   string `json:"old_content,omitempty"`
159		OldDue       string `json:"old_due,omitempty"`
160		OldInterval  int    `json:"old_interval,omitempty"`
161		OldNextDue   string `json:"old_next_due,omitempty"`
162		PartID       string `json:"part_id,omitempty"`
163		Quantity     int    `json:"quantity,omitempty"`
164		WithdrawalID string `json:"withdrawal_id,omitempty"`
