187	func (e eventJSON) toEvent() (Event, error) {
188		t, err := time.Parse(time.RFC3339, e.Time)
189		if err != nil {
190			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
191		}
192		return Event{
193			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
194			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
195			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
196			Decision:   e.Decision,
197			NewContent: e.NewContent, OldContent: e.OldContent,
198			OldDue: e.OldDue, OldInterval: e.OldInterval, OldNextDue: e.OldNextDue,
199			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
200			AttachmentID: e.AttachmentID, Path: e.Path,
201			Time: t,
202		}, nil
203	}
