1	package main
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// 提交-验收通过全流程：提交后工单待验收、资产仍维修中；验收通过后工单按该次
14	// 提交的维修结果关闭，资产恢复可用；履历含提交、验收与关闭三条记录。
15	func TestSubmitApproveLifecycle(t *testing.T) {
16		s := newTestStore(t)
17		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
18			t.Fatal(err)
19		}
20		tk, _, err := s.report("EQ-1", "卡纸", "req-1")
21		if err != nil {
22			t.Fatal(err)
23		}
24	
25		// 提交维修结果：工单转为待验收，返回提交履历的全库序号。
26		tk, submitSeq, err := s.submitRepair(tk.ID, "已更换搓纸轮")
27		if err != nil {
28			t.Fatalf("submitRepair: %v", err)
29		}
30		if tk.Status != ticketPending {
31			t.Fatalf("提交后工单状态 = %q，想得到 %q", tk.Status, ticketPending)
32		}
33		if submitSeq != 2 {
34			t.Fatalf("提交序号 = %d，想得到 2", submitSeq)
35		}
36		if got := s.findAsset("EQ-1").Status; got != statusRepairing {
37			t.Fatalf("待验收时资产应仍为维修中，得到 %q", got)
38		}
39		seq, result, ok := s.currentSubmission(tk.ID)
40		if !ok || seq != submitSeq || result != "已更换搓纸轮" {
41			t.Fatalf("当前待验收提交 = (%d, %q, %v)", seq, result, ok)
42		}
43	
44		// 验收通过：工单按提交的维修结果关闭，资产恢复可用。
45		tk, asset, err := s.acceptSubmission(tk.ID, submitSeq, decisionApprove, "复核通过")
46		if err != nil {
47			t.Fatalf("acceptSubmission: %v", err)
48		}
49		if tk.Status != ticketClosed || tk.Result != "已更换搓纸轮" || tk.ClosedAt == "" {
50			t.Fatalf("验收通过后工单异常: %+v", tk)
51		}
52		if asset.Status != statusAvailable {
53			t.Fatalf("验收通过后资产状态 = %q", asset.Status)
54		}
55	
56		// 履历：提交、验收（含决定、意见与目标序号）、关闭（内容为提交结果）。
57		events := s.eventsOf("EQ-1")
58		if len(events) != 4 {
59			t.Fatalf("履历条数 = %d，想得到 4", len(events))
60		}
61		if events[1].Kind != eventSubmit || events[1].Content != "已更换搓纸轮" || events[1].Seq != submitSeq {
62			t.Fatalf("提交履历不对: %+v", events[1])
63		}
64		if events[2].Kind != eventAccept || events[2].Decision != decisionApprove ||
65			events[2].Content != "复核通过" || events[2].TargetSeq != submitSeq {
66			t.Fatalf("验收履历不对: %+v", events[2])
67		}
68		if events[3].Kind != eventClose || events[3].Content != "已更换搓纸轮" {
69			t.Fatalf("关闭履历不对: %+v", events[3])
70		}
71	
72		// 终结后拒绝提交与验收。
73		if _, _, err := s.submitRepair(tk.ID, "再次提交"); !errors.Is(err, errConflict) {
74			t.Fatalf("已关闭工单提交应失败，得到 %v", err)
75		}
76		if _, _, err := s.acceptSubmission(tk.ID, submitSeq, decisionApprove, "再次验收"); !errors.Is(err, errConflict) {
77			t.Fatalf("已关闭工单验收应失败，得到 %v", err)
78		}
79	
80		// 重载后状态、结果与履历保持；旧请求重放返回已关闭工单。
81		s = saveAndReopen(t, s)
82		tk = s.findTicket("T0001")
83		if tk.Status != ticketClosed || tk.Result != "已更换搓纸轮" {
84			t.Fatalf("重载后工单状态未保持: %+v", tk)
85		}
86		old, replay, err := s.report("EQ-1", "卡纸", "req-1")
87		if err != nil || !replay || old.Status != ticketClosed {
88			t.Fatalf("重载后旧请求重放应返回已关闭工单: %v replay=%v err=%v", old, replay, err)
89		}
90		if got := len(s.eventsOf("EQ-1")); got != 4 {
91			t.Fatalf("重载后履历条数 = %d", got)
92		}
93	
94		// 停机区间：等待验收的时间计入原报修至关闭的停机区间。
95		var reportTime, closeTime int64
96		for _, e := range s.data.Events {
97			switch e.Kind {
98			case eventReport:
99				reportTime = e.Time.Unix()
100			case eventClose:
101				closeTime = e.Time.Unix()
102			}
103		}
104		res, err := s.downtimeForAssets([]string{"EQ-1"},
105			time.Unix(reportTime-10, 0), time.Unix(closeTime+10, 0))
106		if err != nil {
107			t.Fatal(err)
108		}
109		if res[0].Seconds != closeTime-reportTime {
110			t.Fatalf("停机秒数 = %d，想得到 %d", res[0].Seconds, closeTime-reportTime)
111		}
112	}
113	
114	// 返修重提：验收退回后工单恢复未关闭、资产仍维修中，不能绕过验收直接关闭；
115	// 再次提交产生新序号，验收通过后按新提交结果关闭；旧提交与意见全部保留。
116	func TestSubmitRejectAndResubmit(t *testing.T) {
117		s := newTestStore(t)
118		_, _ = s.registerAsset("EQ-1", "打印机", "一楼")
119		tk, _, _ := s.report("EQ-1", "卡纸", "req-1")
120	
121		tk, seq1, err := s.submitRepair(tk.ID, "已清理纸路")
122		if err != nil {
123			t.Fatal(err)
124		}
125		// 重复提交被拒绝。
126		if _, _, err := s.submitRepair(tk.ID, "重复提交"); !errors.Is(err, errConflict) {
127			t.Fatalf("待验收时重复提交应失败，得到 %v", err)
128		}
129		// 验收退回：恢复未关闭，资产仍维修中，不填写维修结果。
130		tk, asset, err := s.acceptSubmission(tk.ID, seq1, decisionReject, "仍有卡纸，需返修")
131		if err != nil {
132			t.Fatalf("验收退回: %v", err)
133		}
134		if tk.Status != ticketOpen || tk.Result != "" {
135			t.Fatalf("退回后工单异常: %+v", tk)
136		}
137		if asset.Status != statusRepairing {
138			t.Fatalf("退回后资产应仍为维修中，得到 %q", asset.Status)
139		}
140		// 退回后不能绕过验收直接关闭。
141		if _, _, err := s.closeTicket(tk.ID, "直接关闭"); !errors.Is(err, errConflict) {
142			t.Fatalf("首次提交后直接关闭应失败，得到 %v", err)
143		}
144		// 再次提交产生新序号。
145		tk, seq2, err := s.submitRepair(tk.ID, "已更换搓纸轮")
146		if err != nil {
147			t.Fatal(err)
148		}
149		if seq2 <= seq1 {
150			t.Fatalf("再次提交序号 %d 应大于首次 %d", seq2, seq1)
151		}
152		// 第二次验收通过：按第二次提交内容关闭。
153		tk, _, err = s.acceptSubmission(tk.ID, seq2, decisionApprove, "复核通过")
154		if err != nil {
155			t.Fatal(err)
156		}
157		if tk.Result != "已更换搓纸轮" {
158			t.Fatalf("维修结果应取第二次提交内容，得到 %q", tk.Result)
159		}
160	
161		// 旧提交与验收意见全部保留：提交×2、验收×2、关闭×1。
162		var submits, accepts, closes int
163		for _, e := range s.eventsOf("EQ-1") {
164			switch e.Kind {
165			case eventSubmit:
166				submits++
167			case eventAccept:
168				accepts++
169				if e.TargetSeq == seq1 && (e.Decision != decisionReject || e.Content != "仍有卡纸，需返修") {
170					t.Fatalf("首次验收履历未保留: %+v", e)
171				}
172			case eventClose:
173				closes++
174			}
175		}
176		if submits != 2 || accepts != 2 || closes != 1 {
177			t.Fatalf("履历统计 = 提交%d/验收%d/关闭%d，想得到 2/2/1", submits, accepts, closes)
178		}
