246	// 待验收期间的限制：拒绝新报修、停用、派工、备件领用退回与重复提交；旧请求
247	// 重放只读返回原单当前状态；待验收可取消，取消后拒绝提交与验收。
248	func TestPendingRestrictions(t *testing.T) {
249		s := newTestStore(t)
250		_, _ = s.registerAsset("EQ-1", "打印机", "一楼")
251		tk, _, _ := s.report("EQ-1", "卡纸", "req-1")
252		if _, err := s.assignTicket(tk.ID, "张三", "首次派工"); err != nil {
253			t.Fatal(err)
254		}
255		p, err := s.withdrawPart(tk.ID, "FILTER-01", 2, "更换滤芯")
256		if err != nil {
257			t.Fatal(err)
258		}
259		if _, _, err := s.submitRepair(tk.ID, "已更换搓纸轮"); err != nil {
260			t.Fatal(err)
261		}
262	
263		// 新报修、停用、派工、领用、退回、重复提交、直接关闭均拒绝。
264		if _, _, err := s.report("EQ-1", "新故障", "req-2"); !errors.Is(err, errConflict) {
265			t.Fatalf("待验收时新报修应失败，得到 %v", err)
266		}
267		if _, err := s.deactivateAsset("EQ-1", "调拨"); !errors.Is(err, errConflict) {
268			t.Fatalf("待验收时停用应失败，得到 %v", err)
269		}
270		if _, err := s.assignTicket(tk.ID, "李四", "转派"); !errors.Is(err, errConflict) {
271			t.Fatalf("待验收时派工应失败，得到 %v", err)
272		}
273		if _, err := s.withdrawPart(tk.ID, "FILTER-02", 1, "再领"); !errors.Is(err, errConflict) {
274			t.Fatalf("待验收时领用应失败，得到 %v", err)
275		}
276		if _, _, err := s.returnPart(p.ID, 1, "多余退回"); !errors.Is(err, errConflict) {
277			t.Fatalf("待验收时退回应失败，得到 %v", err)
278		}
279		if _, _, err := s.submitRepair(tk.ID, "重复提交"); !errors.Is(err, errConflict) {
280			t.Fatalf("待验收时重复提交应失败，得到 %v", err)
281		}
282		if _, _, err := s.closeTicket(tk.ID, "直接关闭"); !errors.Is(err, errConflict) {
283			t.Fatalf("待验收时直接关闭应失败，得到 %v", err)
284		}
285		// 旧请求重放：只读返回原单当前状态（待验收），不新增记录。
286		before := len(s.data.Events)
287		old, replay, err := s.report("EQ-1", "卡纸", "req-1")
288		if err != nil || !replay || old.Status != ticketPending {
289			t.Fatalf("重放应返回待验收原单: %v replay=%v err=%v", old, replay, err)
290		}
291		if len(s.data.Events) != before {
292			t.Fatal("重放不应新增履历")
293		}
294		// detail 仍列出待验收工单。
295		if got := s.openTicketOf("EQ-1"); got == nil || got.ID != tk.ID {
296			t.Fatalf("待验收工单应仍列为未终结，得到 %v", got)
297		}
298	
299		// 待验收可取消：保留提交，不填写维修结果，资产恢复可用。
300		tk, asset, err := s.cancelTicket(tk.ID, "误报，设备实际正常")
301		if err != nil {
302			t.Fatalf("待验收取消: %v", err)
303		}
304		if tk.Status != ticketCancelled || tk.Result != "" {
305			t.Fatalf("取消后工单异常: %+v", tk)
306		}
307		if asset.Status != statusAvailable {
308			t.Fatalf("取消后资产状态 = %q", asset.Status)
309		}
310		if !s.hasSubmission(tk.ID) {
311			t.Fatal("取消后提交履历应保留")
312		}
313		// 终结后拒绝提交与验收。
314		if _, _, err := s.submitRepair(tk.ID, "再提交"); !errors.Is(err, errConflict) {
315			t.Fatalf("已取消工单提交应失败，得到 %v", err)
316		}
317		if _, _, err := s.acceptSubmission(tk.ID, 3, decisionApprove, "x"); !errors.Is(err, errConflict) {
318			t.Fatalf("已取消工单验收应失败，得到 %v", err)
319		}
320		// 退回备件在终结后同样拒绝（旧单操作不影响新单）。
321		if _, _, err := s.returnPart(p.ID, 1, "多余退回"); !errors.Is(err, errConflict) {
322			t.Fatalf("终结后退回应失败，得到 %v", err)
323		}
324	}
