477					"kind": "提交", "content": "已加氟", "time": "2026-10-01T10:00:00Z",
478				})
479				// T0001 的验收指向 T0002 的提交序号。
480				appendTo(m, "events", acceptEvent(7, "T0001", 6, "通过"))
481			}, "履历矛盾"},
482		}
483		for _, tc := range cases {
484			t.Run(tc.name, func(t *testing.T) {
