571		}
572		if saveErr == nil {
573			t.Skip("当前环境允许只读目录写入，跳过保存失败分支")
574		}
575		rawNow, err := os.ReadFile(path)
576		if err != nil || !bytes.Equal(rawNow, rawBefore) {
577			t.Fatal("保存失败不应留下部分变化")
578		}
579		if err := s.save(); err != nil {
580			t.Fatalf("恢复后重试保存应成功: %v", err)
581		}
582	
583		// 重载后待验收状态与提交序号保持，验收同样可重试。
584		s2, err := openStore(s.dir)
585		if err != nil {
586			t.Fatal(err)
587		}
588		tk2 := s2.findTicket("T0001")
589		if tk2.Status != ticketPending {
590			t.Fatalf("重载后应为待验收，得到 %q", tk2.Status)
591		}
592		if got, _, ok := s2.currentSubmission("T0001"); !ok || got != seq {
593			t.Fatalf("重载后提交序号 = %d, %v；想得到 %d, true", got, ok, seq)
594		}
595		rawMid, _ := os.ReadFile(path)
596		if _, _, err := s2.acceptSubmission("T0001", seq, decisionApprove, "复核通过"); err != nil {
597			t.Fatal(err)
598		}
599		if err := os.Chmod(s2.dir, 0o555); err != nil {
600			t.Fatal(err)
601		}
602		saveErr = s2.save()
603		if err := os.Chmod(s2.dir, 0o755); err != nil {
604			t.Fatal(err)
605		}
606		if saveErr == nil {
607			t.Skip("当前环境允许只读目录写入，跳过验收保存失败分支")
608		}
609		rawNow, _ = os.ReadFile(path)
610		if !bytes.Equal(rawNow, rawMid) {
611			t.Fatal("验收保存失败不应留下部分变化")
612		}
613		if err := s2.save(); err != nil {
614			t.Fatalf("恢复后验收重试保存应成功: %v", err)
615		}
616		s3, err := openStore(s.dir)
617		if err != nil {
618			t.Fatal(err)
619		}
620		if got := s3.findTicket("T0001"); got.Status != ticketClosed || got.Result != "已更换搓纸轮" {
621			t.Fatalf("重试后工单异常: %+v", got)
622		}
623	}
624	
625	// replay 还原截止处的工单状态与待验收提交，后续验收不提前生效。
626	func TestReplayPendingSubmission(t *testing.T) {
627		s := newTestStore(t)
628		_, _ = s.registerAsset("EQ-1", "打印机", "一楼")
629		tk, _, _ := s.report("EQ-1", "卡纸", "req-1")                      // 履历 1
630		_, seq1, _ := s.submitRepair(tk.ID, "第一次结果")                     // 履历 2
631		_, _, _ = s.acceptSubmission(tk.ID, seq1, decisionReject, "返修")  // 履历 3
632		_, seq2, _ := s.submitRepair(tk.ID, "第二次结果")                     // 履历 4
633		_, _, _ = s.acceptSubmission(tk.ID, seq2, decisionApprove, "通过") // 履历 5、6（关闭）
634	
635		// 截止 2：待验收，当前提交为第一次。
636		snap := s.replayAsset("EQ-1", 2)
637		if snap.openTicket == nil || snap.openTicket.status != ticketPending ||
638			snap.openTicket.submitSeq != seq1 || snap.openTicket.submitResult != "第一次结果" {
639			t.Fatalf("截止 2 回看异常: %+v", snap.openTicket)
640		}
641		if snap.status != statusRepairing {
642			t.Fatalf("截止 2 资产状态 = %q", snap.status)
643		}
644		// 截止 3：退回后恢复未关闭，无待验收提交。
645		snap = s.replayAsset("EQ-1", 3)
646		if snap.openTicket == nil || snap.openTicket.status != ticketOpen || snap.openTicket.submitSeq != 0 {
647			t.Fatalf("截止 3 回看异常: %+v", snap.openTicket)
648		}
649		// 截止 4：再次待验收，当前提交为第二次。
650		snap = s.replayAsset("EQ-1", 4)
651		if snap.openTicket == nil || snap.openTicket.status != ticketPending ||
652			snap.openTicket.submitSeq != seq2 || snap.openTicket.submitResult != "第二次结果" {
653			t.Fatalf("截止 4 回看异常: %+v", snap.openTicket)
654		}
655		// 截止 5：验收通过已发生但关闭履历未到，仍待验收（后续关闭不提前生效）。
656		snap = s.replayAsset("EQ-1", 5)
657		if snap.openTicket == nil || snap.openTicket.status != ticketPending {
658			t.Fatalf("截止 5 回看异常: %+v", snap.openTicket)
659		}
660		// 截止 6：工单已关闭，资产可用。
661		snap = s.replayAsset("EQ-1", 6)
662		if snap.openTicket != nil || snap.status != statusAvailable {
663			t.Fatalf("截止 6 回看异常: %+v / %q", snap.openTicket, snap.status)
664		}
665	}
666	
667	// 命令行入口：参数错误退出 2，业务失败退出 1；成功输出提交序号、工单编号与新状态。
668	func TestSubmitAcceptCLI(t *testing.T) {
669		dir := t.TempDir()
670		var out, errBuf bytes.Buffer
671		runCmd := func(args ...string) (int, string, string) {
672			out.Reset()
673			errBuf.Reset()
674			code := run(append(args, "--data-dir", dir), &out, &errBuf)
675			return code, out.String(), errBuf.String()
676		}
677		if code, _, _ := runCmd("register", "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼"); code != 0 {
678			t.Fatal("register 失败")
679		}
680		if code, _, _ := runCmd("report", "--asset-id", "EQ-1", "--description", "卡纸", "--request-id", "req-1"); code != 0 {
681			t.Fatal("report 失败")
682		}
683		// 参数错误：缺少维修结果、非法决定、非法序号。
684		if code, _, _ := runCmd("submit", "--ticket-id", "T0001"); code != 2 {
685			t.Fatalf("缺少维修结果应退出 2，得到 %d", code)
686		}
687		if code, _, _ := runCmd("accept", "--ticket-id", "T0001", "--seq", "1", "--decision", "待定", "--comment", "x"); code != 2 {
688			t.Fatalf("非法决定应退出 2，得到 %d", code)
689		}
690		if code, _, _ := runCmd("accept", "--ticket-id", "T0001", "--seq", "0", "--decision", "通过", "--comment", "x"); code != 2 {
691			t.Fatalf("非法序号应退出 2，得到 %d", code)
692		}
693		// 业务失败：未知工单提交、未提交工单验收。
694		if code, _, _ := runCmd("submit", "--ticket-id", "T9999", "--repair-result", "x"); code != 1 {
695			t.Fatalf("未知工单提交应退出 1，得到 %d", code)
696		}
697		if code, _, _ := runCmd("accept", "--ticket-id", "T0001", "--seq", "1", "--decision", "通过", "--comment", "x"); code != 1 {
698			t.Fatalf("无待验收提交时验收应退出 1，得到 %d", code)
699		}
700		// 提交成功：输出提交序号与待验收状态。
701		code, stdout, _ := runCmd("submit", "--ticket-id", "T0001", "--repair-result", "已更换搓纸轮")
702		if code != 0 || !strings.Contains(stdout, "提交序号: ") || !strings.Contains(stdout, "工单状态: 待验收") {
703			t.Fatalf("提交输出异常（%d）: %s", code, stdout)
704		}
705		// ticket 显示当前待验收提交；detail 仍列出待验收工单。
706		code, stdout, _ = runCmd("ticket", "--ticket-id", "T0001")
707		if code != 0 || !strings.Contains(stdout, "待验收提交序号: ") || !strings.Contains(stdout, "待验收提交结果: 已更换搓纸轮") {
708			t.Fatalf("ticket 输出异常（%d）: %s", code, stdout)
709		}
710		code, stdout, _ = runCmd("detail", "--asset-id", "EQ-1")
711		if code != 0 || !strings.Contains(stdout, "未关闭工单: T0001") {
712			t.Fatalf("detail 输出异常（%d）: %s", code, stdout)
713		}
714		// 待验收时直接关闭失败（退出 1）。
715		if code, _, _ := runCmd("close", "--ticket-id", "T0001", "--repair-result", "绕过验收"); code != 1 {
716			t.Fatalf("待验收直接关闭应退出 1，得到 %d", code)
717		}
718		// 验收通过：显示工单编号及新状态，资产恢复可用。
719		code, stdout, _ = runCmd("accept", "--ticket-id", "T0001", "--seq", "2", "--decision", "通过", "--comment", "复核通过")
720		if code != 0 || !strings.Contains(stdout, "T0001") || !strings.Contains(stdout, "工单状态: 已关闭") ||
721			!strings.Contains(stdout, "当前状态: 可用") {
722			t.Fatalf("验收输出异常（%d）: %s", code, stdout)
723		}
724		// history 展示提交、验收与关闭的内容、关联与时间。
725		code, stdout, _ = runCmd("history", "--asset-id", "EQ-1")
726		if code != 0 || !strings.Contains(stdout, "提交 工单 T0001: 已更换搓纸轮") ||
727			!strings.Contains(stdout, "验收 工单 T0001: 通过，目标提交序号 2（复核通过）") {
728			t.Fatalf("history 输出异常（%d）: %s", code, stdout)
729		}
730		// ticket 对非待验收工单明确提示无待验收提交。
731		code, stdout, _ = runCmd("ticket", "--ticket-id", "T0001")
732		if code != 0 || !strings.Contains(stdout, "待验收提交: 无") {
733			t.Fatalf("ticket 输出异常（%d）: %s", code, stdout)
734		}
735	}
