118		}
119		if t.Status == ticketPending {
120			return nil, fmt.Errorf("%w: 工单 %s 处于待验收，不能领用备件", errConflict, ticketID)
121		}
122		if partID == "" {
123			return nil, fmt.Errorf("%w: 备件编号不能为空", errConflict)
124		}
125		if note == "" {
126			return nil, fmt.Errorf("%w: 领用说明不能为空", errConflict)
127		}
128		if quantity < 1 {
129			return nil, fmt.Errorf("%w: 领用数量须为正整数", errConflict)
130		}
131		// 先确认领用编号与履历计数器都能推进，再修改任何业务数据：
132		// 编号耗尽时拒绝领用，不消耗编号，也不产生履历。
133		seq := s.data.NextPartSeq
134		if seq < 1 || seq == math.MaxInt {
135			return nil, fmt.Errorf("%w: 领用编号计数器已耗尽，无法分配新领用编号", errConflict)
136		}
137		eventSeq, err := s.nextEventSeq()
138		if err != nil {
139			return nil, err
140		}
141		p := &PartWithdrawal{
142			ID:       fmt.Sprintf("P%04d", seq),
143			TicketID: t.ID,
144			AssetID:  t.AssetID,
145			PartID:   partID,
146			Quantity: quantity,
147			Note:     note,
148		}
149		s.data.NextPartSeq = seq + 1
150		s.data.Parts = append(s.data.Parts, p)
151		s.appendPartEvent(eventSeq, p, eventPartWithdraw, quantity, note)
152		return p, nil
153	}
