155	// returnPart 按领用编号退回备件：作用于该笔领用所属的工单，允许多次部分退回，
156	// 累计不得超过该笔原数量，也不能冲减另一笔。成功时更新累计退回并追加一条退回
157	// 履历。失败路径不修改任何业务数据。
158	func (s *store) returnPart(withdrawalID string, quantity int, reason string) (*PartWithdrawal, *Ticket, error) {
159		p := s.findPart(withdrawalID)
160		if p == nil {
161			return nil, nil, fmt.Errorf("%w: 未知领用编号 %q", errNotFound, withdrawalID)
162		}
163		t := s.findTicket(p.TicketID)
164		if t == nil {
165			return nil, nil, fmt.Errorf("数据内部错误：领用记录 %s 引用的工单不存在", withdrawalID)
166		}
167		if t.Status == ticketClosed {
168			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能退回备件", errConflict, t.ID)
169		}
170		if t.Status == ticketCancelled {
171			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能退回备件", errConflict, t.ID)
172		}
173		if t.Status == ticketPending {
174			return nil, nil, fmt.Errorf("%w: 工单 %s 处于待验收，不能退回备件", errConflict, t.ID)
175		}
176		if reason == "" {
177			return nil, nil, fmt.Errorf("%w: 退回理由不能为空", errConflict)
178		}
179		if quantity < 1 {
180			return nil, nil, fmt.Errorf("%w: 退回数量须为正整数", errConflict)
181		}
182		// 剩余可退数量 = 原数量 - 累计退回（两者均在 [0, 原数量] 内，减法不会溢出）；
183		// 退回数量超过剩余即拒绝。不做 Returned+quantity 的加法比较：大数量相加
184		// 可能整数溢出回绕成负数，从而错误接受超额退回。
185		if quantity > p.Quantity-p.Returned {
186			return nil, nil, fmt.Errorf(
187				"%w: 备件数量问题：领用记录 %s 原数量 %d，已退回 %d，再退 %d 将超过原数量",
188				errConflict, p.ID, p.Quantity, p.Returned, quantity)
189		}
190		eventSeq, err := s.nextEventSeq()
191		if err != nil {
192			return nil, nil, err
193		}
194		p.Returned += quantity
195		s.appendPartEvent(eventSeq, p, eventPartReturn, quantity, reason)
196		return p, t, nil
197	}
