			// 通过或取消终结，退回后也不能绕过验收直接关闭。
			if submittedEver[e.TicketID] {
				return fmt.Errorf("履历矛盾：工单 %s 首次提交后只能验收通过或取消终结，却出现直接关闭履历（序号 %d）",
