212	func (t *ticketRepair) applyClose(e Event) error {
213		switch t.state {
214		case ticketOpen:
215			if t.submittedEver {
216				return &repairRuleError{code: chainCloseAfterSubmit, ticketID: e.TicketID, seq: e.Seq, state: t.state}
217			}
218		case derivedApproved:
219			if e.Content != t.approvedResult {
220				return &repairRuleError{
221					code: chainCloseResultMismatch, ticketID: e.TicketID, seq: e.Seq, state: t.state,
222				}
223			}
224		default:
225			return &repairRuleError{code: chainCloseBadState, ticketID: e.TicketID, seq: e.Seq, state: t.state}
226		}
227		t.state = ticketClosed
228		t.approvedResult = ""
229		return nil
230	}
