233	// 保留全部提交履历且不填写维修结果。终态工单不能再取消。
234	func (t *ticketRepair) applyCancel(e Event) error {
235		if t.state != ticketOpen && t.state != ticketPending {
236			return &repairRuleError{code: chainCancelBadState, ticketID: e.TicketID, seq: e.Seq, state: t.state}
237		}
238		t.state = ticketCancelled
239		t.pendingSeq = 0
240		t.pendingResult = ""
241		return nil
242	}

